//! Queue groups declared in [`topics!`](crate::topics) with `[ … ]`.

use std::any::{Any, TypeId};
use std::hash::{Hash, Hasher};
use std::sync::Arc;

/// A group enum generated by [`topics!`](crate::topics). Each value is
/// one group: `Indexer(0)` and `Indexer(1)` are two groups.
#[diagnostic::on_unimplemented(
    message = "`{Self}` isn't a queue group",
    note = "declare queue groups in `topics!` with `[ … ]` on a topic"
)]
pub trait QueueGroup: Eq + Hash + Send + Sync + 'static {}

/// The group enum `Self` belongs to the scope `S`: a channel with the scope
/// `S` can join its queue groups. `S` is the `Topic` enum of the level that
/// declares them, or for a leaf the group enum itself.
#[diagnostic::on_unimplemented(
    message = "queue group `{Self}` isn't declared on this topic",
    label = "declared on another topic",
    note = "a queue group can only be joined on the topic that declares it"
)]
pub trait InScope<S> {}

/// Object-safe view of a [`QueueGroup`], to key groups by value.
trait GroupValue: Send + Sync + 'static {
    fn as_any(&self) -> &dyn Any;
    fn eq_value(&self, other: &dyn GroupValue) -> bool;
    fn hash_value(&self, state: &mut dyn Hasher);
    #[cfg(feature = "tracing")]
    fn type_name(&self) -> &'static str;
}

impl<G: QueueGroup> GroupValue for G {
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn eq_value(&self, other: &dyn GroupValue) -> bool {
        other.as_any().downcast_ref::<G>() == Some(self)
    }
    fn hash_value(&self, mut state: &mut dyn Hasher) {
        TypeId::of::<G>().hash(&mut state);
        self.hash(&mut state);
    }
    #[cfg(feature = "tracing")]
    fn type_name(&self) -> &'static str {
        std::any::type_name::<G>()
    }
}

/// A queue group value, compared by type and value.
#[derive(Clone)]
pub(crate) struct GroupKey(Arc<dyn GroupValue>);

impl GroupKey {
    pub(crate) fn new(group: impl QueueGroup) -> Self {
        Self(Arc::new(group))
    }
}

impl PartialEq for GroupKey {
    fn eq(&self, other: &Self) -> bool {
        self.0.eq_value(&*other.0)
    }
}

impl Eq for GroupKey {}

impl Hash for GroupKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.0.hash_value(state);
    }
}

/// The group enum's type: group values need not implement `Debug`.
#[cfg(feature = "tracing")]
impl std::fmt::Debug for GroupKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.0.type_name())
    }
}
